def _normalize_pii_key(key: object) -> str:
    """`stripeSecretKey`, `API-Key` and `first name` become `stripe_secret_key`, `api_key`, `first_name`."""
    out: list[str] = []
    previous = ""
    for char in str(key):
        if char.isupper() and (previous.islower() or previous.isdigit()):
            out.append("_")
        out.append(char.lower() if char.isalnum() else "_")
        previous = char
    return "".join(out)


def _is_pii_key(key: object) -> bool:
    normalized = _normalize_pii_key(key)
    if normalized in _PII_KEYS:
        return True
    padded = f"_{normalized}_"
    return any(segment in padded for segment in _PII_SEGMENTS)


def _sanitize_pii(value: Any, enabled: bool) -> Any:
    """Recursively redact known credential and direct-identifier fields."""
    if not enabled:
        return value
    if isinstance(value, dict):
        return {
            key: _PII_REDACTION_MARKER if _is_pii_key(key) else _sanitize_pii(item, enabled)
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [_sanitize_pii(item, enabled) for item in value]
    if isinstance(value, tuple):
        return tuple(_sanitize_pii(item, enabled) for item in value)
    return value
